import{_ as t}from"./chunks/image4.-AF4PoMn.js";import{_ as a}from"./chunks/image133.B1u_Iusd.js";import{_ as n,o as i,c as o,ag as s}from"./chunks/framework.CxkNbRKf.js";const r="/nada-documentation/images/image146.png",l="/nada-documentation/images/image147.png",c="/nada-documentation/images/image148.png",d="/nada-documentation/images/image149.png",h="/nada-documentation/images/image150.png",p="/nada-documentation/images/image151.png",m="/nada-documentation/images/image152.png",u="/nada-documentation/images/image153.png",g="/nada-documentation/images/image154.png",x=JSON.parse('{"title":"Managing facets","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/facets.md","filePath":"admin-guide/web-ui/facets.md","lastUpdated":1786379412000}'),f={name:"admin-guide/web-ui/facets.md"};function y(b,e,q,_,w,A){return i(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="managing-facets" tabindex="-1">Managing facets <a class="header-anchor" href="#managing-facets" aria-label="Permalink to &quot;Managing facets&quot;">​</a></h1><p>Facets (filters) play a critical role in making data more discoverable. The following facets are displayed by default in NADA:</p><ul><li><p>Range of years</p></li><li><p>Country</p></li><li><p>Data type (shown only when a catalog includes entries of more than one type)</p></li></ul><p><img src="'+r+'" alt=""></p><p>You can add your own facets and apply them to each data type independently. Facets must be created based on metadata elements in the standard standards and schemas. They only make sense when the metadata element is categorical and has a reasonably small number of categories. When metadata are documented using CVs, make it easier. All metadata schemas used in NADA have an element &quot;tags&quot; that provides much flexibility to create custom facets.</p><p><img src="'+t+'" alt=""></p><h2 id="creating-a-new-facet" tabindex="-1">Creating a new facet <a class="header-anchor" href="#creating-a-new-facet" aria-label="Permalink to &quot;Creating a new facet&quot;">​</a></h2><h2 id="using-the-administrator-interface" tabindex="-1">Using the administrator interface <a class="header-anchor" href="#using-the-administrator-interface" aria-label="Permalink to &quot;Using the administrator interface&quot;">​</a></h2><p>To manage facets, click on Settings &gt; Facets in the main menu.</p><p><img src="'+a+'" alt=""></p><p><img src="'+l+'" alt=""></p><p>Click on <strong>Create new facet</strong>. In each relevant schema, you will have to identify the element that corresponds to the facet being created. In some cases, a facet will apply to only one data type (for example, a facet &quot;Document type&quot; would only apply to entries of type &quot;document&quot;). In others, it can apply to multiple data types. A few facets other than the ones provided by default in NADA (year, type, country) may cover all data types (this could be the case of &quot;topics&quot;, &quot;keywords&quot;, or &quot;tags&quot;).</p><p>In the Create Facet form, you will provide a short name for the facet, a title (header to be displayed in the user interface), and a status (Enabled/Disabled).</p><p><img src="'+c+'" alt=""></p><p>In the <strong>Field</strong> section, select the metadata field that correspond to your facet. For example, if you create a facet to allow users to filter documents by their publishing status (the document schema suggests the use of a controlled vocabulary for this field with possible values &quot;first draft, draft, reviewed draft, final draft, final&quot;), you will select the field &quot;document_description/status&quot;.</p><p><strong>Subfields</strong>: Some metadata fields may have more than one component. For example, the field &quot;language&quot; has a component &quot;name&quot; and a component &quot;code&quot;. If you want to use the name of the language in the filter, you will have to select the element &quot;name&quot;. The fields that contain more than one component are identified with a * in the drop-down list.</p><p><img src="'+d+'" alt=""></p><p><strong>Filter and Filter value</strong>: These options allow you to limit the filter to some specific values in the metadata. An example of the use of filter and filter value is provided below in the section &quot;Use of tags for custom facets&quot;.</p><p>After creating a new facet, you must click on the <strong>Indexer</strong> button to reindex the metadata in your catalog. Without doing this, the facet will not be displayed in your catalog.</p><p><img src="'+h+'" alt=""></p><h2 id="using-the-api" tabindex="-1">Using the API <a class="header-anchor" href="#using-the-api" aria-label="Permalink to &quot;Using the API&quot;">​</a></h2><p>Facets cannot be created using the API in NADA 5.2.0.</p><h2 id="activating-and-ordering-facets" tabindex="-1">Activating and ordering facets <a class="header-anchor" href="#activating-and-ordering-facets" aria-label="Permalink to &quot;Activating and ordering facets&quot;">​</a></h2><h2 id="using-the-administrator-interface-1" tabindex="-1">Using the administrator interface <a class="header-anchor" href="#using-the-administrator-interface-1" aria-label="Permalink to &quot;Using the administrator interface&quot;">​</a></h2><p>To activate the facets and change the order in which they appear in the user interface, click on Configure.</p><p><img src="'+p+'" alt=""></p><p>The different data types are displayed in tabs where all available facets are listed. In each tab, select the facet you want to display in the corresponding data type tabs in the user interface (setting them as On/Off). The order of the facets can be modified by drag and drop. When a change is made in the selection and/or order, click on <strong>Update</strong> to save it.</p><p><img src="'+m+'" alt=""></p><h2 id="using-the-api-1" tabindex="-1">Using the API <a class="header-anchor" href="#using-the-api-1" aria-label="Permalink to &quot;Using the API&quot;">​</a></h2><p>Facets cannot be managed using the API in NADA 5.2.0.</p><h2 id="use-of-tags-for-custom-facets" tabindex="-1">Use of tags for custom facets <a class="header-anchor" href="#use-of-tags-for-custom-facets" aria-label="Permalink to &quot;Use of tags for custom facets&quot;">​</a></h2><p>Tags provide a very convenient and flexible solution to generate customized tags based on information that may not be found in the specific elements found in the metadata schemas. The &quot;tags&quot; field available in all metadata schemas contains two elements: tag, and tag_group.</p><p><img src="'+u+'" alt=""></p><p>Let&#39;s assume you want to create a facet that would apply to ALL data types and filter entries by pricing policy, with two possible options: &quot;For free&quot; or &quot;For a fee&quot;. No metadata schema using in NADA other than the Document schema provides an element related to the pricing policy. The NADA API makes it easy to add this information to the metadata for all catalog entries, in a tag. The &quot;tag&quot; would contain value &quot;For free&quot; or &quot;For a fee&quot;, and in all cases the tag_group would be named &quot;fee_or_free&quot;. A new facet can then be created with the following parameters:</p><ul><li><p>Name: <em>pricing</em></p></li><li><p>Title: <em>Pricing policy</em></p></li><li><p>Mapping: <em>tags</em> (for all data types)</p></li><li><p>Filter: <em>tag_group</em></p></li><li><p>Filter value: <em>fee_or_free</em></p></li></ul><p><img src="'+g+'" alt=""></p><p>The selection of the &quot;tags&quot; field and the filter and filter value must be entered for ALL data types. After saving it and reindexing, a new facet will be available that will apply to the tags that belong to the group &quot;fee_or_free&quot; (ignoring all other tags that may have been entered in the metadata).</p><h2 id="using-the-api-2" tabindex="-1">Using the API <a class="header-anchor" href="#using-the-api-2" aria-label="Permalink to &quot;Using the API&quot;">​</a></h2><p>Facets cannot be managed using the API in NADA 5.2.0.</p>',39)])])}const I=n(f,[["render",y]]);export{x as __pageData,I as default};
